/**
 * Macro to flip Vehicle and Spacecraft tokens. In v0.23.3 the token
 * images for spacecraft and vehicles have been flipped from pointing
 *'up' to pointing 'down'. This is to match the Foundry guidelines.
 * This is mostly for the auto-rotate feature.
 *
 * This is only needed for the token images built into the MgT2e
 * system. Any images you've added yourself won't be affected.
 *
 * Select some tokens and run this macro. The mirror-X and mirror-Y
 * options will be toggled on them. This means you can re-run it to
 * put things back. It also works on tokens which are rotation locked.
 * It only affects tokens of type Spacecraft or Vehicle.
 */
let tokens = canvas.tokens.controlled;
let number = canvas.tokens.controlled.length;
let title = `Mirror ${number} selected tokens?`;
if (number === 0) {
  ui.notifications.error("You must select at least one token");
  return;
}

const yesno = await foundry.applications.api.DialogV2.confirm({
  window: { title: title },
  content: `<p>All selected Spacecraft and Vehicle tokens will be flipped. Other token types will be ignored.</p>`,
  rejectClose: false,
  modal: true
});

if (yesno) {
  for (const token of tokens) {
    if (["vehicle", "spacecraft"].includes(token.document.actor.type)) {
      const texture = token.document.texture;
      texture.scaleX = texture.scaleX * -1;
      texture.scaleY = texture.scaleY * -1;
      token.document.update({ texture: texture });
    }
  }
} else {
  console.log("No");
}
